def enclosed(n,pts):
    wall=set(pts); vis=set(); q=deque()
    for r in range(n):
      for c in (0,n-1):
       if (r,c) not in wall and (r,c) not in vis: vis.add((r,c));q.append((r,c))
    for c in range(n):
      for r in (0,n-1):
       if (r,c) not in wall and (r,c) not in vis: vis.add((r,c));q.append((r,c))
    while q:
      r,c=q.popleft()
      for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
       if 0<=p[0]<n and 0<=p[1]<n and p not in wall and p not in vis: vis.add(p);q.append(p)
    return {(r,c) for r in range(n) for c in range(n) if (r,c) not in wall and (r,c) not in vis}
