def transform_fill(n,tracks):
 # tracks mapping d to inclusive s range, with parity matching
 out=set()
 ds=sorted(tracks)
 # take adjacent globally and overlap ranges
 for d1,d2 in zip(ds,ds[1:]):
  lo=max(tracks[d1][0],tracks[d2][0]); hi=min(tracks[d1][1],tracks[d2][1])
  if lo>hi: continue
  for r in range(n):
   for c in range(n):
    s=r+c; d=c-r
    if lo<=s<=hi and d1<d<d2:out.add((r,c))
 return out
